-- Seed data, not a schema change: run with the data tool after 01 is applied.

-- Six version-1 checklists from Emily's draft, plus one switch per category (all off).

SELECT set_config('resolve.checklist_publish', 'on', true);

INSERT INTO public.playbooks (category, title, active, playbook_key, version, status, approved_at, effective_on, applies_to, source, source_refs, checklist, checklist_category, sop_url)
SELECT 'checklist', 'Lockout or access problem', false, 'checklist:lockout', 1, 'approved', now(), current_date, ARRAY['ticket'], 'imported', ARRAY['Resolve Ticket Checklists: Draft for Review (Nov 4 2026)'], '{"priority":{"activeGuest":"p1","otherwise":"p2"},"steps":[{"key":"guest","label":"1","question":"Have you responded to the guest?","options":[{"value":"yes","label":"Yes, responded"},{"value":"not_yet","label":"Not yet","keepsOpen":true}],"activeGuestOnly":true,"guestResponse":true,"facts":["guest"]},{"key":"problem","label":"2","question":"Which problem?","options":[{"value":"code","label":"Code not working"},{"value":"dead","label":"Lock dead or offline"},{"value":"wrong_code","label":"Lost or wrong code sent"},{"value":"hardware","label":"Door or hardware broken"}]},{"key":"remote_fix","label":"3","question":"Try the remote fix on {lock_system}: resend the correct code, send the backup code, or reset the lock. Did it work?","options":[{"value":"yes","label":"Yes"},{"value":"no","label":"No"}],"facts":["lock_system"]},{"key":"inside","label":"3a","question":"Guest confirmed they''re inside?","options":[{"value":"yes","label":"Yes","goto":"lock_cause"}],"showIf":{"step":"remote_fix","answers":["yes"]}},{"key":"vendor","label":"4","question":"Send a vendor: locksmith or handyman from the vendor list, then Send to Breezeway or Email the work order.","options":[{"value":"sent","label":"Vendor sent"}],"action":"fix_flow","showIf":{"step":"remote_fix","answers":["no"]}},{"key":"vendor_wait","label":"5","question":"Waiting on vendor: appointment time set? Guest told when help is coming?","options":[{"value":"yes","label":"Yes"}],"showIf":{"step":"remote_fix","answers":["no"]}},{"key":"lock_cause","label":"6","question":"Was the lock or code the cause?","options":[{"value":"yes","label":"Yes","effect":"Flags the home for a lock check"},{"value":"no","label":"No"}]},{"key":"refund","label":"7","question":"Does the guest need a refund or credit?","options":[{"value":"yes","label":"Yes","action":"refund"},{"value":"no","label":"No"}],"facts":["refund_limits"]},{"key":"close","label":"8","question":"Close the ticket. Is anything keeping the home from being guest-ready?","options":[{"value":"no","label":"No, close it","action":"close"},{"value":"yes","label":"Yes","action":"follow_up","noteRequired":true,"effect":"Opens a follow-up"}]}]}'::jsonb, 'lockout', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.playbooks WHERE checklist IS NOT NULL AND checklist_category = 'lockout');

INSERT INTO public.playbooks (category, title, active, playbook_key, version, status, approved_at, effective_on, applies_to, source, source_refs, checklist, checklist_category, sop_url)
SELECT 'checklist', 'Cleaning complaint', false, 'checklist:cleaning', 1, 'approved', now(), current_date, ARRAY['ticket'], 'imported', ARRAY['Resolve Ticket Checklists: Draft for Review (Nov 4 2026)'], '{"priority":null,"steps":[{"key":"guest","label":"1","question":"Have you responded to the guest?","options":[{"value":"yes","label":"Yes, responded"},{"value":"not_yet","label":"Not yet","keepsOpen":true}],"activeGuestOnly":true,"guestResponse":true,"facts":["guest"]},{"key":"photos","label":"2","question":"Get photos or video from the guest.","options":[{"value":"attached","label":"Attached"},{"value":"wont_send","label":"Guest won''t send"}]},{"key":"cleaner_notes","label":"3","question":"Check the cleaner''s notes in Breezeway: marked clean? Dirty status left from a cancelled booking?","options":[{"value":"checked","label":"Notes checked"}],"facts":["last_stay"]},{"key":"reclean","label":"4","question":"Offer a re-clean. Did they accept?","help":"A re-clean offer is required before a cleaning-fee refund.","options":[{"value":"yes","label":"Yes"},{"value":"no","label":"No, refusal recorded","noteRequired":true}],"facts":["next_clean"]},{"key":"reclean_done","label":"4a","question":"Schedule the re-clean through Breezeway. Done and guest satisfied?","options":[{"value":"yes","label":"Yes","goto":"item"}],"showIf":{"step":"reclean","answers":["yes"]}},{"key":"fee_refund","label":"5","question":"Refund the cleaning fee first.","help":"Choose \"Cleaning fee\" in the refund form.","options":[{"value":"logged","label":"Refund logged","action":"refund"}],"showIf":{"step":"reclean","answers":["no"]},"facts":["refund_limits"]},{"key":"rent_comp","label":"6","question":"If still unhappy: escalate to rent compensation (refund limits apply).","options":[{"value":"satisfied","label":"Guest is satisfied"},{"value":"escalated","label":"Escalated to rent compensation","action":"refund"}],"showIf":{"step":"reclean","answers":["no"]},"facts":["refund_limits"]},{"key":"item","label":"7","question":"Specific item cleaning hasn''t fixed (stain, odor, damaged linen)?","options":[{"value":"no","label":"No"},{"value":"repair","label":"Yes, open a work order","action":"fix_flow"},{"value":"buy","label":"Yes, buy a replacement","action":"purchase"}]},{"key":"repeat","label":"8","question":"Repeat complaint for the same cleaner? If so, flag the cleaning team lead.","options":[{"value":"checked","label":"Checked"}]},{"key":"close","label":"9","question":"Close the ticket. Is anything keeping the home from being guest-ready?","options":[{"value":"no","label":"No, close it","action":"close"},{"value":"yes","label":"Yes","action":"follow_up","noteRequired":true,"effect":"Opens a follow-up"}]}]}'::jsonb, 'cleaning', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.playbooks WHERE checklist IS NOT NULL AND checklist_category = 'cleaning');

INSERT INTO public.playbooks (category, title, active, playbook_key, version, status, approved_at, effective_on, applies_to, source, source_refs, checklist, checklist_category, sop_url)
SELECT 'checklist', 'Maintenance or repair', false, 'checklist:maintenance', 1, 'approved', now(), current_date, ARRAY['ticket'], 'imported', ARRAY['Resolve Ticket Checklists: Draft for Review (Nov 4 2026)'], '{"priority":null,"steps":[{"key":"what","label":"1","question":"What''s broken?","options":[{"value":"hvac","label":"HVAC"},{"value":"plumbing","label":"Plumbing"},{"value":"electrical","label":"Electrical"},{"value":"appliance","label":"Appliance"},{"value":"handyman","label":"Handyman"},{"value":"other","label":"Other"}],"fields":[{"key":"line","label":"One line","required":true,"kind":"text"}]},{"key":"guest","label":"2","question":"Have you responded to the guest?","options":[{"value":"yes","label":"Yes, responded"},{"value":"not_yet","label":"Not yet","keepsOpen":true}],"activeGuestOnly":true,"guestResponse":true,"facts":["guest","next_arrival"]},{"key":"emergency","label":"3","question":"Emergency? (active leak, no heat or AC in extreme weather, safety hazard)","options":[{"value":"yes","label":"Yes","noteRequired":true,"effect":"Proceed now and record why. Owner approval can follow."},{"value":"no","label":"No"}]},{"key":"vendor","label":"4","question":"Choose the vendor (suggested approved vendors for the trade and market).","options":[{"value":"chosen","label":"Vendor chosen"}],"action":"fix_flow"},{"key":"quote","label":"5","question":"Quote or estimated cost.","help":"Thresholds are per issue and cumulative.","options":[{"value":"saved","label":"Save"}],"fields":[{"key":"amount","label":"Quote or estimate ($)","required":true,"kind":"money"}],"facts":["repair_band"]},{"key":"dispatch","label":"6","question":"Dispatch: Send to Breezeway or Email the work order.","options":[{"value":"sent","label":"Sent"}],"action":"fix_flow"},{"key":"owner_email","label":"7","question":"Owner email sent within 1 business day, CC Micah Sinor and James Miller?","options":[{"value":"yes","label":"Yes"}],"showIfApproval":{"step":"quote","field":"amount"}},{"key":"calendar","label":"8","question":"Calendar block needed?","options":[{"value":"yes","label":"Yes","action":"calendar_block","effect":"Block in OwnerRez and notify the owner"},{"value":"no","label":"No"}]},{"key":"done","label":"9","question":"Work done? Upload vendor photo or invoice.","options":[{"value":"uploaded","label":"Uploaded"}],"action":"work_order"},{"key":"after","label":"10","question":"Anything else to schedule after this fix (maintenance, staging, cleaner)? Anything keeping the home from guest-ready?","options":[{"value":"no","label":"No"},{"value":"yes","label":"Yes","action":"follow_up","noteRequired":true,"effect":"Opens a follow-up"}]},{"key":"close","label":"11","question":"Close the ticket. Is anything keeping the home from being guest-ready?","options":[{"value":"no","label":"No, close it","action":"close"},{"value":"yes","label":"Yes","action":"follow_up","noteRequired":true,"effect":"Opens a follow-up"}]}]}'::jsonb, 'maintenance', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.playbooks WHERE checklist IS NOT NULL AND checklist_category = 'maintenance');

INSERT INTO public.playbooks (category, title, active, playbook_key, version, status, approved_at, effective_on, applies_to, source, source_refs, checklist, checklist_category, sop_url)
SELECT 'checklist', 'Other guest complaint', false, 'checklist:other_complaint', 1, 'approved', now(), current_date, ARRAY['ticket'], 'imported', ARRAY['Resolve Ticket Checklists: Draft for Review (Nov 4 2026)'], '{"priority":null,"steps":[{"key":"guest","label":"1","question":"Have you responded to the guest?","options":[{"value":"yes","label":"Yes, responded"},{"value":"not_yet","label":"Not yet","keepsOpen":true}],"activeGuestOnly":true,"guestResponse":true,"facts":["guest"]},{"key":"about","label":"2","question":"About?","options":[{"value":"wifi_tv","label":"Wi-Fi or TV"},{"value":"missing","label":"Missing item or amenity"},{"value":"noise","label":"Noise or neighbor"},{"value":"listing","label":"Listing didn''t match"},{"value":"other","label":"Other"}]},{"key":"remote","label":"3","question":"Fixed remotely?","options":[{"value":"yes","label":"Yes"},{"value":"visit","label":"No, someone needs to go to the home","action":"fix_flow"},{"value":"buy","label":"No, something needs buying","action":"purchase"}]},{"key":"safety","label":"4","question":"Noise or neighbor: safety concern?","options":[{"value":"yes","label":"Yes","action":"escalate","effect":"Escalate to the Supervisor now"},{"value":"no","label":"No"}],"showIf":{"step":"about","answers":["noise"]}},{"key":"resolved","label":"5","question":"Guest confirmed resolved?","options":[{"value":"yes","label":"Yes"},{"value":"not_yet","label":"Not yet","keepsOpen":true}],"fields":[{"key":"next_update","label":"Next update time","required":false,"kind":"datetime"}]},{"key":"refund","label":"6","question":"Refund or credit?","options":[{"value":"yes","label":"Yes","action":"refund"},{"value":"no","label":"No"}],"facts":["refund_limits"]},{"key":"listing","label":"7","question":"Listing or house manual change needed?","options":[{"value":"yes","label":"Yes","noteRequired":true},{"value":"no","label":"No"}]},{"key":"close","label":"8","question":"Close the ticket. Is anything keeping the home from being guest-ready?","options":[{"value":"no","label":"No, close it","action":"close"},{"value":"yes","label":"Yes","action":"follow_up","noteRequired":true,"effect":"Opens a follow-up"}]}]}'::jsonb, 'other_complaint', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.playbooks WHERE checklist IS NOT NULL AND checklist_category = 'other_complaint');

INSERT INTO public.playbooks (category, title, active, playbook_key, version, status, approved_at, effective_on, applies_to, source, source_refs, checklist, checklist_category, sop_url)
SELECT 'checklist', 'Damage and claim', false, 'checklist:damage', 1, 'approved', now(), current_date, ARRAY['ticket'], 'imported', ARRAY['Resolve Ticket Checklists: Draft for Review (Nov 4 2026)'], '{"priority":null,"steps":[{"key":"what","label":"1","question":"What was damaged? Description and photos are required.","options":[{"value":"attached","label":"Photos attached"}],"fields":[{"key":"description","label":"Description","required":true,"kind":"text"}]},{"key":"stay","label":"2","question":"Which stay caused it?","options":[{"value":"confirmed","label":"Confirmed"},{"value":"different","label":"A different stay","noteRequired":true}],"facts":["last_stay"]},{"key":"blocks","label":"3","question":"Stops the next check-in?","options":[{"value":"yes","label":"Yes","action":"fix_flow","effect":"Urgent: opens the repair. Check whether a calendar block is needed."},{"value":"no","label":"No"}],"facts":["next_arrival"]},{"key":"cost","label":"4","question":"Repair or replace: quote or receipt.","options":[{"value":"saved","label":"Save"}],"fields":[{"key":"amount","label":"Amount ($)","required":true,"kind":"money"}]},{"key":"payer","label":"5","question":"Who pays? You propose; the Supervisor confirms only when the owner or ARHA pays.","options":[{"value":"platform","label":"Guest via Airbnb or Vrbo claim","action":"claim"},{"value":"deposit","label":"Security deposit","action":"claim"},{"value":"owner","label":"Owner","action":"escalate","effect":"Supervisor confirms"},{"value":"arha","label":"ARHA absorbs","action":"escalate","effect":"Supervisor confirms"}]},{"key":"filed","label":"6","question":"Claim filed? Record the platform deadline.","options":[{"value":"filed","label":"Filed","action":"claim"}],"fields":[{"key":"deadline","label":"Platform deadline","required":true,"kind":"datetime"}]},{"key":"result","label":"7","question":"Received or denied?","options":[{"value":"received","label":"Received"},{"value":"denied","label":"Denied","action":"escalate","effect":"Goes to the Supervisor"},{"value":"waiting","label":"Still waiting","keepsOpen":true}]},{"key":"close","label":"8","question":"Close the ticket. Is anything keeping the home from being guest-ready?","help":"Finance sees the result.","options":[{"value":"no","label":"No, close it","action":"close"},{"value":"yes","label":"Yes","action":"follow_up","noteRequired":true,"effect":"Opens a follow-up"}]}]}'::jsonb, 'damage', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.playbooks WHERE checklist IS NOT NULL AND checklist_category = 'damage');

INSERT INTO public.playbooks (category, title, active, playbook_key, version, status, approved_at, effective_on, applies_to, source, source_refs, checklist, checklist_category, sop_url)
SELECT 'checklist', 'Booking or reservation issue', false, 'checklist:booking', 1, 'approved', now(), current_date, ARRAY['ticket'], 'imported', ARRAY['Notion SOP: Early Check-in/Late Checkout Requests (verified)'], '{"priority":null,"settings":[{"key":"eci_fee_3pm","label":"Early check-in at 3:00 PM","value":"free"},{"key":"eci_fee_2pm","label":"Early check-in at 2:00 PM","value":"$55"},{"key":"eci_fee_before_1pm","label":"Early check-in before 1:00 PM","value":"$75"},{"key":"lco_fee_11am","label":"Late checkout at 11:00 AM","value":"$55"},{"key":"lco_fee_noon","label":"Late checkout at noon","value":"$75"},{"key":"lco_fee_after_noon","label":"Late checkout after noon","value":"$145"}],"steps":[{"key":"guest","label":"1","question":"Have you responded to the guest?","options":[{"value":"yes","label":"Yes, responded"},{"value":"not_yet","label":"Not yet","keepsOpen":true}],"activeGuestOnly":true,"guestResponse":true,"facts":["guest"]},{"key":"request","label":"2","question":"Request?","options":[{"value":"early","label":"Early check-in"},{"value":"late","label":"Late checkout"},{"value":"dates","label":"Change dates"},{"value":"extend","label":"Extend stay"},{"value":"cancel","label":"Cancel"},{"value":"double","label":"Double booking"},{"value":"payment","label":"Payment problem"}]},{"key":"eci_cleaner","label":"3","question":"Early check-in. Cleaner approved the time?","help":"Check the prior night''s occupancy and the Breezeway departure clean. Fee by time: 3:00 PM {eci_fee_3pm}, 2:00 PM {eci_fee_2pm}, before 1:00 PM {eci_fee_before_1pm}.","options":[{"value":"yes","label":"Yes"},{"value":"no","label":"No, decline","effect":"Decline the request"}],"showIf":{"step":"request","answers":["early"]},"facts":["last_stay","next_clean"]},{"key":"eci_payment","label":"3a","question":"Payment collected before confirming?","options":[{"value":"yes","label":"Yes"},{"value":"free","label":"Free"}],"showIf":{"step":"eci_cleaner","answers":["yes"]}},{"key":"eci_notes","label":"3b","question":"Breezeway and OwnerRez notes updated?","options":[{"value":"yes","label":"Yes"}],"showIf":{"step":"eci_cleaner","answers":["yes"]}},{"key":"lco_same_day","label":"4","question":"Late checkout. Is there a same-day arrival?","help":"Fee by time: 11:00 AM {lco_fee_11am}, noon {lco_fee_noon}, after noon {lco_fee_after_noon}.","options":[{"value":"yes","label":"Yes, decline","effect":"Decline the request"},{"value":"no","label":"No"}],"showIf":{"step":"request","answers":["late"]},"facts":["next_arrival"]},{"key":"lco_clean_moves","label":"4a","question":"Does the clean move past 4:00 PM or to the next day?","options":[{"value":"yes","label":"Yes","action":"calendar_block","effect":"Block the calendar in OwnerRez so no booking lands before the home is ready"},{"value":"no","label":"No"}],"showIf":{"step":"lco_same_day","answers":["no"]},"facts":["next_clean"]},{"key":"lco_notes","label":"4b","question":"Cleaner notified, Breezeway updated, request recorded in OwnerRez?","options":[{"value":"yes","label":"Yes"}],"showIf":{"step":"lco_same_day","answers":["no"]}},{"key":"waiver","label":"5","question":"Fee waiver or discount?","help":"A waiver or discount needs Supervisor approval.","options":[{"value":"none","label":"No waiver"},{"value":"waiver","label":"Waiver or discount","action":"escalate","effect":"Needs Supervisor approval"}],"showIf":{"step":"request","answers":["early","late"]}},{"key":"next_guest","label":"6","question":"Could this affect the next guest?","options":[{"value":"yes","label":"Yes, decline","effect":"Decline the request"},{"value":"no","label":"No"}],"showIf":{"step":"request","answers":["early","late"]},"facts":["next_arrival"]},{"key":"retract","label":"7","question":"Does ARHA need to retract an approval for an operational reason?","help":"If so, refund the fee and apologize to the guest.","options":[{"value":"no","label":"No"},{"value":"yes","label":"Yes, refund the fee","action":"refund"}],"showIf":{"step":"request","answers":["early","late"]},"facts":["refund_limits"]},{"key":"free","label":"8","question":"Change dates or extend: is the home free?","help":"Anything not plainly free on the calendar is an exception for the Supervisor.","options":[{"value":"yes","label":"Yes"},{"value":"exception","label":"Not plainly free","action":"escalate","effect":"Supervisor exception"}],"showIf":{"step":"request","answers":["dates","extend"]},"facts":["reservation","next_arrival"]},{"key":"double","label":"9","question":"Double booking (P1). Which stay keeps the home?","help":"Relocation needs the Director regardless of cost.","options":[{"value":"decided","label":"Decided"},{"value":"relocate","label":"Relocation needed","action":"escalate","effect":"Needs the Director"}],"fields":[{"key":"keeps","label":"Stay that keeps the home","required":true,"kind":"text"}],"showIf":{"step":"request","answers":["double"]}},{"key":"changed","label":"10","question":"Made the change in OwnerRez?","options":[{"value":"yes","label":"Yes"}]},{"key":"refund","label":"11","question":"Refund or credit?","options":[{"value":"yes","label":"Yes","action":"refund"},{"value":"no","label":"No"}],"facts":["refund_limits"]},{"key":"close","label":"12","question":"Close the ticket. Is anything keeping the home from being guest-ready?","options":[{"value":"no","label":"No, close it","action":"close"},{"value":"yes","label":"Yes","action":"follow_up","noteRequired":true,"effect":"Opens a follow-up"}]}]}'::jsonb, 'booking', NULL
WHERE NOT EXISTS (SELECT 1 FROM public.playbooks WHERE checklist IS NOT NULL AND checklist_category = 'booking');

